 4486: # no request is spent) in the SAME child environment as a turn of $Auth, 15 s. Its JSON is read
 4487: # BEFORE its exit code: loggedIn false -> missing ("not signed in"), whatever the exit code;
 4488: # loggedIn true -> ok when the route is the one the roster names: subscription - authMethod
 4489: # claude.ai; api-key - ANTHROPIC_API_KEY set in this process (checked before anything starts); an
 4490: # apiProvider other than firstParty (a gateway, Bedrock, Vertex, Foundry - D10) or another
 4491: # authMethod -> missing. No launcher -> missing; not started, a timeout, no JSON or no loggedIn ->
 4492: # unknown ("not checked"). No credentials-file fallback. Only authMethod, apiProvider and
 4493: # projectsDirectory are kept (the cache, for the ledger's provider_config and the launch check) -
 4494: # never the account's e-mail or organisation.
 4495: $script:ClaudeSignInCache = @{}
 4496: function Get-ClaudeSignIn {
 4497:     param([string]$Launcher = '', [int]$TimeoutSec = 15, [string]$Auth = 'subscription')
 4498:     if ($script:ClaudeAuthModes -notcontains $Auth) { $Auth = 'subscription' }
 4499:     if (-not $Launcher) { return (New-CredentialResult 'missing' 'claude CLI not found on PATH') }
 4500:     if ($Auth -eq 'api-key') {
 4501:         $key = [Environment]::GetEnvironmentVariable('ANTHROPIC_API_KEY')
 4502:         if (-not $key -or -not $key.Trim()) { return (New-CredentialResult 'missing' 'ANTHROPIC_API_KEY is not set (roster auth api-key)') }
 4503:     }
 4504:     $t = $(if ($TimeoutSec -gt 0) { [Math]::Min($TimeoutSec, 15) } else { 15 })
 4505:     $cap = Invoke-ClaudeProbe -Launcher $Launcher -Arguments 'auth status' -TimeoutSec $t -Auth $Auth
 4506:     if (-not $cap.Started) { return (New-CredentialResult 'unknown' "not checked - ``claude auth status`` could not be started$(if ($cap.Why) { " ($($cap.Why))" })") }
 4507:     if ($cap.TimedOut) { return (New-CredentialResult 'unknown' "not checked - ``claude auth status`` did not finish within $t s") }
 4508:     $o = $null
 4509:     $out = [string]$cap.Out
 4510:     $a = $out.IndexOf('{'); $b = $out.LastIndexOf('}')
 4511:     if ($a -ge 0 -and $b -gt $a) { try { $o = ConvertFrom-Json -InputObject $out.Substring($a, $b - $a + 1) } catch { $o = $null } }
 4512:     $out = $null
 4513:     if (-not (Test-IsJsonObject $o)) { return (New-CredentialResult 'unknown' "not checked - ``claude auth status`` printed no JSON object (exit $($cap.Exit))") }
 4514:     $li = Get-PropertyValue $o 'loggedIn' $null
 4515:     $am = ConvertTo-ClaudeToken (Get-PropertyValue $o 'authMethod' $null)
 4516:     $ap = ConvertTo-ClaudeToken (Get-PropertyValue $o 'apiProvider' $null)
 4517:     $pd = Get-PropertyValue $o 'projectsDirectory' $null
 4518:     $o = $null
 4519:     $script:ClaudeSignInCache["$Launcher|$Auth"] = [pscustomobject]@{ AuthMethod = $am; ApiProvider = $ap; ProjectsDirectory = $(if ($pd -is [string]) { $pd } else { '' }) }
 4520:     if ($li -eq $false) { return (New-CredentialResult 'missing' 'not signed in (`claude auth status`: loggedIn false; run `claude auth login`)') }
 4521:     if ($li -ne $true) { return (New-CredentialResult 'unknown' "not checked - ``claude auth status`` names no loggedIn (exit $($cap.Exit))") }
 4522:     if ($ap -and $ap -cne 'firstParty') { return (New-CredentialResult 'missing' "apiProvider $ap - routes other than Anthropic's own API (a gateway, Bedrock, Vertex, Foundry) are out of scope for the claude engine") }
 4523:     if ($Auth -eq 'subscription') {
 4524:         if ($am -cne 'claude.ai') { return (New-CredentialResult 'missing' "signed in with authMethod $(if ($am) { $am } else { '(none)' }), not the claude.ai subscription the roster names (auth subscription; an API key is auth api-key)") }
 4525:         return (New-CredentialResult 'ok' 'signed in (claude.ai subscription)')
 4526:     }
 4527:     return (New-CredentialResult 'ok' "signed in (ANTHROPIC_API_KEY set$(if ($am) { "; authMethod $am" }))")
 4528: }
